import type { Shape } from "../types";

/** Pre-rendered gallery thumbnails (`public/examples/thumbs.json`, generated by `scripts/gen-thumbs.ts`). */
export interface ThumbEntry { hash: string; paths: { d: string; fill: boolean }[] }
export type ThumbsFile = Record<string, ThumbEntry>;

/** Hash of the shapes an example produces — used to detect a stale thumbs.json. */
export function thumbsHash(shapes: Shape[]): string {
  const str = JSON.stringify(shapes);
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16);
}

let cached: Promise<ThumbsFile> | null = null;
/** Load thumbs.json once (empty object when missing/offline). */
export function loadThumbs(fetchFn: typeof fetch = fetch): Promise<ThumbsFile> {
  if (!cached) {
    cached = fetchFn("/examples/thumbs.json").then((r) => (r.ok ? (r.json() as Promise<ThumbsFile>) : {})).catch(() => ({}));
  }
  return cached;
}
/** Tests. */
export function _resetThumbs() { cached = null; }
